<?php use kartik\select2\Select2;use yii\helpers\Html;use yii\widgets\ActiveForm;$form=ActiveForm::begin()?>
<div class="card card-success card-outline"><div class="card-body"><div class="row"><div class="col-md-6"><?=$form->field($model,'academic_period')->dropDownList($periods)?><?=$form->field($model,'study_program_id')->widget(Select2::class,['data'=>$programs,'options'=>['placeholder'=>'Pilih Program Studi']])?><?=$form->field($model,'new_student_curriculum_year_id')->widget(Select2::class,['data'=>$curriculumYears,'options'=>['placeholder'=>'Pilih Kurikulum'],'pluginOptions'=>['allowClear'=>true]])?></div><div class="col-md-6"><?=$form->field($model,'notes')->textarea(['rows'=>7])?></div></div><hr><div class="row"><?php foreach($model::booleanLabels() as $attribute=>$label):?><div class="col-md-4"><?=$form->field($model,$attribute)->checkbox(['label'=>$label])?></div><?php endforeach?></div><div class="text-right"><?=Html::submitButton('<i class="fas fa-save"></i> Simpan',['class'=>'btn btn-success'])?> <?=Html::a('Batal',['index'],['class'=>'btn btn-warning'])?></div></div></div><?php ActiveForm::end()?>
